392: func (l *raftLog) term(i uint64) (uint64, error) {
393: 	// Check the unstable log first, even before computing the valid term range,
394: 	// which may need to access stable Storage. If we find the entry's term in
395: 	// the unstable log, we know it was in the valid range.
396: 	if t, ok := l.unstable.maybeTerm(i); ok {
397: 		return t, nil
398: 	}
