400: 	// The valid term range is [firstIndex-1, lastIndex]. Even though the entry at
401: 	// firstIndex-1 is compacted away, its term is available for matching purposes
402: 	// when doing log appends.
403: 	if i+1 < l.firstIndex() {
404: 		return 0, ErrCompacted
405: 	}
406: 	if i > l.lastIndex() {
407: 		return 0, ErrUnavailable
408: 	}
