477: // scan visits all log entries in the [lo, hi) range, returning them via the
478: // given callback. The callback can be invoked multiple times, with consecutive
479: // sub-ranges of the requested range. Returns up to pageSize bytes worth of
480: // entries at a time. May return more if a single entry size exceeds the limit.
481: //
482: // The entries in [lo, hi) must exist, otherwise scan() eventually returns an
483: // error (possibly after passing some entries through the callback).
484: //
485: // If the callback returns an error, scan terminates and returns this error
486: // immediately. This can be used to stop the scan early ("break" the loop).
487: func (l *raftLog) scan(lo, hi uint64, pageSize entryEncodingSize, v func([]pb.Entry) error) error {
488: 	for lo < hi {
489: 		ents, err := l.slice(lo, hi, pageSize)
490: 		if err != nil {
491: 			return err
492: 		} else if len(ents) == 0 {
493: 			return fmt.Errorf("got 0 entries in [%d, %d)", lo, hi)
494: 		}
495: 		if err := v(ents); err != nil {
496: 			return err
497: 		}
498: 		lo += uint64(len(ents))
499: 	}
500: 	return nil
501: }
