1934: 	last := r.raftLog.lastEntryID()
1935: 	r.logger.Infof("%x [commit: %d, lastindex: %d, lastterm: %d] restored snapshot [index: %d, term: %d]",
1936: 		r.id, r.raftLog.committed, last.index, last.term, id.index, id.term)
